pub trait Greeter {
    fn greet(&self, name: &str) -> String;
}

pub struct Polite {
    pub prefix: String,
}

impl Greeter for Polite {
    fn greet(&self, name: &str) -> String {
        decorate(&self.prefix, name)
    }
}

pub struct Loud;

impl Greeter for Loud {
    fn greet(&self, name: &str) -> String {
        shout(name)
    }
}

fn decorate(prefix: &str, name: &str) -> String {
    format!("{} {}", prefix, name)
}

fn shout(name: &str) -> String {
    format!("{}!!!", name)
}

// Generic (static) trait dispatch — resolves CHA-style to every Greeter impl.
pub fn run_generic<G: Greeter>(g: &G) -> String {
    g.greet("world")
}

// Dynamic dispatch — charon leaves this as a vtable Call (the documented gap).
pub fn run_dyn(g: &dyn Greeter) -> String {
    g.greet("world")
}

